client_script:
frappe.web_form.after_load = () => {
	const qs = new URLSearchParams(window.location.search);
	const enq = qs.get("enquiry"), tok = qs.get("t");
	if (enq) {
		frappe.web_form.set_value("enquiry", enq);
		if (tok) {
			frappe.call({ method: "tnc_v2_360ithub.tnc_v2.doctype.student_enquiry.student_enquiry.admission_prefill", args: { enquiry: enq, t: tok } }).then((r) => {
				const v = r.message || {};
				Object.keys(v).forEach((k) => { if (v[k] && !frappe.web_form.get_value(k)) frappe.web_form.set_value(k, v[k]); });
				if (v.student_name) frappe.web_form.set_value("student_name", (v.student_name || "").toUpperCase());
			});
		}
	}
	frappe.call({ method: "tnc_v2_360ithub.admissions.terms.terms_html_api" }).then((r) => {
		const f = frappe.web_form.fields_dict.terms_html;
		if (f && f.$wrapper) f.$wrapper.html(r.message || "");
	});
	const btn = () => $(".web-form-footer .btn-primary, .web-form-actions .btn-primary, .web-form .btn-primary[type=submit]");
	const sync = () => btn().prop("disabled", !frappe.web_form.get_value("terms_accepted"));
	setTimeout(sync, 300);
	frappe.web_form.on("terms_accepted", sync);
};
frappe.web_form.validate = () => {
	if (!frappe.web_form.get_value("terms_accepted")) {
		frappe.msgprint(__("कृपया नियम एवं शर्तें स्वीकार करें। / Please accept the rules and consent to continue."));
		return false;
	}
	const m = (frappe.web_form.get_value("mobile") || "").replace(/\D/g, "");
	if (m.length < 10) { frappe.msgprint(__("Please enter a valid 10-digit mobile number.")); return false; }
	return true;
};
